import{z as o,x as i,o as t,c as s,q as r,j as l,D as e,d as E,s as n,S as d,b as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"波动率产品的对冲","description":"","frontmatter":{"title":"波动率产品的对冲","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vt-product-hedging.md","filePath":"quant/vt-product-hedging.md","lastUpdated":1791063341000}'),p={name:"quant/vt-product-hedging.md"};function D(m,a,u,h,C,f){const A=i("Mermaid");return t(),s("div",null,[a[2]||(a[2]=r('<h1 id="波动率产品的对冲" tabindex="-1">波动率产品的对冲 <a class="header-anchor" href="#波动率产品的对冲" aria-label="Permalink to &quot;波动率产品的对冲&quot;">​</a></h1><div class="epigraph"><p>对冲方差互换，就是对冲它的复制条带；产品越「纯波动」，对冲越像一份记账工作——直到跳、截断与结算规则把账本重新打开。</p><footer>—— 据 Carr and Madan, 1998；Demeterfi, Derman, Kamal and Zou, 1999 整理</footer></div><p><a href="/quant/vt-crossmarket-vol">上一课</a>把波动预算铺到跨市场；本课回到产品层，回答「持有这些合同的人每天对冲什么」。复制课讲了条带怎么定价，方差互换深化课拆了持有期四栏账；本课把它们落成逐日执行的 delta 手册：每个产品的 delta 从哪来、用什么工具对、剩下的基差记在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>方差互换号称「纯方差暴露」，但它的盯市与 delta 来自一个期权条带；不对冲条带，空头在跌市里被动接 gamma。VIX 期货的 delta 又落在另一套条带与期货上；波动互换、Gamma swap、相关互换各不相同。产品之间「名字像、delta 不像」，混用一份对冲手册，跌市里每个产品都会以自己特有的方式出错。</p><h3 id="按产品列-delta-手册" tabindex="-1">按产品列 delta 手册 <a class="header-anchor" href="#按产品列-delta-手册" aria-label="Permalink to &quot;按产品列 delta 手册&quot;">​</a></h3><p>方差互换：delta 就是复制条带的 delta，集中在平值附近，用标的期货对冲；权重 \\(1/K^2\\) 使大跌后手数按凸性上升。<span class="marginnote">\\(1/K^2\\) 是条带里每档期权的配手规则：行权价 80 与 100 的两档，权重比是 \\((1/80^2):(1/100^2)\\approx 1.56:1\\)，越低的行权价配的手数越多。于是现货大跌、期权批量变成实值时，条带手数自动放大——这就是空头「跌市里被动接 gamma」的数学来源。</span>波动互换：在方差 delta 上乘开方凸性调整，差额靠小面积期权补（<a href="/quant/var-vs-vol-swap">方差与波动互换</a>）。<a href="/quant/gamma-swap">Gamma swap</a>：复制权重 \\(1/K\\)，delta 单侧偏重，与方差互换的价差本身是偏度仓位，对冲不得共用一套手数。VIX 期货：标的是未来三十天条带的平方根，delta 拆到两腿期权与<a href="/quant/vix-futures">VIX 定价</a>的凸性项，还带一条到期的日历腿。相关互换：没有一阶工具，只能用分散篮子近似并接受残差（<a href="/quant/correlation-swap">相关互换</a>）。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对冲按「复制镜像」组织：理论上合同等于条带，于是「持有合同加反向条带」等于现金加固定利息，剩下的一切都是基差。执行三步。一，建仓日把条带手数、到期、权重存成台账，delta 由台账实时算出，不由模型情绪决定。二，每日按<a href="/quant/delta-hedge-freq">对冲频率</a>的带宽用期货回补，条带自身的 Theta 与 Gamma 流水进四栏账。三，滚动与到期：条带随时间向近月挪，方差桶跟着挪（深化课的桶口径）；结算基差单独记账——OTC 合同的 RV 口径与上市产品的结算规则不同，VIX 的开仓算法与 SPX/SPXW 截止都要写进合同附件级文档。</p>',9)),(t(),l(d,null,{default:e(()=>[n(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E6%96%B9%E5%B7%AE%E4%BA%92%E6%8D%A2%22%5D%20--%3E%20STRIP%5B%22%E5%A4%8D%E5%88%B6%E6%9D%A1%E5%B8%A6%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20P2%5B%22%E6%B3%A2%E5%8A%A8%E4%BA%92%E6%8D%A2%22%5D%20--%3E%20CONV%5B%22%E5%BC%80%E6%96%B9%E5%87%B8%E6%80%A7%E8%B0%83%E6%95%B4%22%5D%0A%20%20P3%5B%22Gamma%20swap%22%5D%20--%3E%20W1K%5B%221%2FK%20%E6%9D%83%E9%87%8D%E6%89%8B%E6%95%B0%22%5D%0A%20%20P4%5B%22VIX%20%E6%9C%9F%E8%B4%A7%22%5D%20--%3E%20VIX%5B%22%E4%B8%A4%E8%85%BF%E6%9C%9F%E6%9D%83%E5%8A%A0%E5%87%B8%E6%80%A7%E9%A1%B9%22%5D%0A%20%20STRIP%20--%3E%20DH%5B%22%E6%AF%8F%E6%97%A5%E6%9C%9F%E8%B4%A7%E5%AF%B9%E5%86%B2%E6%8C%89%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20CONV%20--%3E%20DH%0A%20%20W1K%20--%3E%20DH%0A%20%20VIX%20--%3E%20DH%0A%20%20DH%20--%3E%20ROLL%5B%22%E5%B1%95%E6%9C%9F%E6%BB%9A%E5%8A%A8%20%E6%96%B9%E5%B7%AE%E6%A1%B6%22%5D%0A%20%20DH%20--%3E%20BASIS%5B%22%E5%9F%BA%E5%B7%AE%E8%B4%A6%EF%BC%9A%E6%88%AA%E6%96%AD%20%E8%B7%B3%20%E7%BB%93%E7%AE%97%E8%A7%84%E5%88%99%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[E("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,[E("为什么对冲不能消除凸性与跳：条带复制在扩散与连续路径下才与合同相等，跳余项与截断是复制本身的缺口，对冲只是在合同与条带之间搬运风险。这份「搬不平」的清单——离散条带对连续理论的偏差、跳跃余项、结算口径差——就是产品对冲的全部残差来源，也是"),B("a",{href:"/quant/short-vol-tail"},"波动率卖方"),E("尾部的藏身处。它必须显式列账，而不是摊进滑点。")],-1)),(t(),l(d,null,{default:e(()=>[n(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%8C%81%E6%9C%89%E5%90%88%E5%90%8C%22%5D%20--%3E%20B%7B%22%E5%90%88%E5%90%8C%E7%9C%9F%E7%9A%84%E7%AD%89%E4%BA%8E%E6%9D%A1%E5%B8%A6%E5%90%97%22%7D%0A%20%20B%20--%3E%7C%22%E8%BF%9E%E7%BB%AD%E6%89%A9%E6%95%A3%E8%B7%AF%E5%BE%84%22%7C%20C%5B%22%E6%88%90%E7%AB%8B%EF%BC%9A%E5%8A%A0%E5%8F%8D%E5%90%91%E6%9D%A1%E5%B8%A6%20%E5%8F%AA%E5%89%A9%E5%9F%BA%E5%B7%AE%22%5D%0A%20%20B%20--%3E%7C%22%E8%B7%B3%E4%BD%99%E9%A1%B9%22%7C%20D%5B%22%E7%BC%BA%E5%8F%A3%E4%B8%80%EF%BC%9A%E8%B7%B3%E8%B7%83%E6%97%A0%E6%B3%95%E5%AF%B9%E5%86%B2%22%5D%0A%20%20B%20--%3E%7C%22%E6%9D%A1%E5%B8%A6%E5%8F%AA%E6%9C%89%E6%9C%89%E9%99%90%E6%A1%A3%E8%A1%8C%E6%9D%83%E4%BB%B7%22%7C%20E%5B%22%E7%BC%BA%E5%8F%A3%E4%BA%8C%EF%BC%9A%E7%A6%BB%E6%95%A3%E5%8C%96%E5%81%8F%E5%B7%AE%22%5D%0A%20%20B%20--%3E%7C%22%E7%BB%93%E7%AE%97%E5%8F%A3%E5%BE%84%E4%B8%8D%E5%90%8C%22%7C%20F%5B%22%E7%BC%BA%E5%8F%A3%E4%B8%89%EF%BC%9ARV%20%E4%B8%8E%E7%BB%93%E7%AE%97%E8%A7%84%E5%88%99%E4%B9%8B%E5%B7%AE%22%5D%0A%20%20D%20--%3E%20G%5B%22%E6%AE%8B%E5%B7%AE%E8%B4%A6%20%E6%98%BE%E5%BC%8F%E5%88%97%E8%B4%A6%22%5D%0A%20%20E%20--%3E%20G%0A%20%20F%20--%3E%20G%0A%20%20G%20--%3E%20H%5B%22%E5%8E%8B%E5%8A%9B%E6%97%A5%E9%9B%86%E4%B8%AD%E5%85%91%E7%8E%B0%E7%9A%84%E5%B0%BE%E9%83%A8%E4%BA%8F%E6%8D%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">常见误区：以为「做了对冲」就等于「消除了风险」。对冲只是把价格方向的风险换成合同与条带之间的差价（基差）；平时这个差价小到像手续费，跳空与结算日才集中兑现。所以残差要单独记账，而不是事后当滑点摊掉。</span></p><p>对冲生态里还有一个内生对手方：<a href="/quant/vol-etp-rebalance-flow">Vol ETP 的每日再平衡流</a>由产品规则决定，压力日放大期货端需求。对冲自己的 VIX 期货腿时，要把「ETP 流会在什么时候、以多大规模进场」当市场状态读，执行预算给这种流留深度。<span class="marginnote">ETP 再平衡流像一台定了闹钟的洒水器：不管庄稼渴不渴，到点就按产品公式放水。对冲交易员因此可以把「几点会有多少买盘」当成可预告的天气来排执行计划，只在规模上为压力日留足深度余量。</span></p><p><span class="marginnote">条带 delta 主要由平值跨式贡献：现货大跌后，对冲手数按凸性上升而不是线性上升。方差互换空头的对冲预算要按「跌百分之五的次日账单」留，不按平均日留——这是该产品最常被打穿的一条假设。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理 OTC 信用与抵押，不写执行滑点的微观结构，也不推导 VIX 期权的定价凸性（在 <a href="/quant/vix-futures">VIX 定价</a>课）。相关互换的篮子构造与权重漂移是 dispersion 课的主题，这里只关心它作为对冲工具的残差。最后一条边界：所有产品的 delta 都随现货与时间连续变化，手册给的是规则与台账格式，不是免检的自动档。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>产品名字像、delta 不像：方差、波动、Gamma swap、VIX 期货、相关互换各有自己的 delta 来源。</li><li>对冲是复制的记账镜像：合同加反向条带理论上只剩基差。</li><li>残差三源：条带离散化、跳余项、结算口径差，必须显式列账。</li><li>展期按方差桶滚动，台账先于模型：delta 由台账实时算出。</li><li>ETP 再平衡流是内生对手方，执行预算按压力日深度留。</li><li>出处：Carr and Madan, 1998；Demeterfi, Derman, Kamal and Zou, 1999；各产品细节见链接课程。</li></ul>',7))])}const q=o(p,[["render",D]]);export{c as __pageData,q as default};
